window.NARRATION = {"ci_a": {"dur": 22.72, "text": "Pressure shows how you actually lead. This is where you start to see the gap between instinct and intention. Take about 30 seconds on each of these. Write what actually went on inside you, rather than what you think should have happened. Only you can see what you write, and it's saved here so you can come back to it. Select Save on each one as you go, then select Next.", "sents": [[0.03, "Pressure shows how you actually lead.", 0], [2.93, "This is where you start to see the gap between instinct and intention.", 0], [7.35, "Take about 30 seconds on each of these.", 1], [9.97, "Write what actually went on inside you, rather than what you think should have happened.", 1], [14.69, "Only you can see what you write, and it's saved here so you can come back to it.", 1], [19.05, "Select Save on each one as you go, then select Next.", 2]], "v": "k1", "cues": [0.03, 7.35, 19.05]}, "ci_b": {"dur": 10.8, "text": "Now look at what you wrote and pick the pattern that's closest to it. There's no right answer. Naming a habit helps you catch it sooner next time, so pick the one that best reflects your experience.", "sents": [[0.01, "Now look at what you wrote and pick the pattern that's closest to it.", 0], [3.75, "There's no right answer.", 1], [5.23, "Naming a habit helps you catch it sooner next time, so pick the one that best reflects your experience.", 1]], "v": "k1", "cues": [0.01, 3.75]}, "ci_c": {"dur": 20.08, "text": "Now run the Foundation Reset. Say your five words, the ones you saved on the Foundation Reset screen. Ask yourself for two next-best steps. Pick the one you'll take in the next ten minutes. Then take one breath and answer the anchor on the last card. It takes about a minute and works best standing up, so do it now before you move on.", "sents": [[0, "Now run the Foundation Reset.", 0], [2.15, "Say your five words, the ones you saved on the Foundation Reset screen.", 1], [6.37, "Ask yourself for two next-best steps.", 1], [9.07, "Pick the one you'll take in the next ten minutes.", 1], [11.71, "Then take one breath and answer the anchor on the last card.", 1], [15.41, "It takes about a minute and works best standing up, so do it now before you move on.", 2]], "v": "k1", "cues": [0, 2.15, 15.41]}, "kc_retry": {"dur": 3.68, "text": "Not quite. Have another look, then try again.", "sents": [[0.05, "Not quite.", 0], [1.45, "Have another look, then try again.", 0]], "v": "v4l", "cues": [0.05]}, "n_3_0": {"dur": 11.84, "text": "Lesson 3 is where you draft your M.V.P.: your mission, your vision, and your purpose. It takes about 40 minutes here, then one core rep this week. Select Start Lesson.", "sents": [[0.01, "Lesson 3 is where you draft your M.V.P.: your mission, your vision, and your purpose.", 0], [6.39, "It takes about 40 minutes here, then one core rep this week.", 1], [10.35, "Select Start Lesson.", 1]], "v": "k1", "cues": [0.01, 6.39]}, "n_3_1": {"dur": 18.56, "text": "Read this moment. Which way would you lean? Before you decide, ask yourself: “Which choice gets me closer to the leader I'm becoming, not just the opportunity that's hardest to say no to?” This lesson gives you a way to answer: a purpose, a vision, and a mission you've actually written down.", "sents": [[0, "Read this moment.", 0], [1.71, "Which way would you lean?", 0], [3.27, "Before you decide, ask yourself: “Which choice gets me closer to the leader I'm becoming, not just the opportunity that's hardest to say no to?”", 1], [12.27, "This lesson gives you a way to answer: a purpose, a vision, and a mission you've actually written down.", 1]], "v": "v4l", "cues": [0, 3.27]}, "n_3_10": {"dur": 10.24, "text": "Try sorting these. For each statement, decide whether it's a purpose, a vision, or a mission. A tip: the mission says what you will do and for whom.", "sents": [[0.03, "Try sorting these.", 0], [1.55, "For each statement, decide whether it's a purpose, a vision, or a mission.", 0], [6.37, "A tip: the mission says what you will do and for whom.", 1]], "v": "v4l", "cues": [0.03, 6.37]}, "n_3_12": {"dur": 40.0, "text": "A year is too long to plan in detail, and a week is too short to build momentum. Ninety days is long enough to finish something real. Each season runs the same loop. You plan two or three goals tied to your M.V.P., execute daily and weekly, reflect every week, then reset. Your Scorecard holds the whole season. Part 1 holds the M.V.P. you draft in this lesson. Parts 2 to 4, your Core 4 Play, your game plan, and your weekly check-ins, come in Lesson 5. Parts 5 and 6, the monthly reflection, then the assessment and reset, come in Lesson 6. Open it this week and have a look.", "sents": [[0.05, "A year is too long to plan in detail, and a week is too short to build momentum.", 0], [5.95, "Ninety days is long enough to finish something real.", 0], [9.67, "Each season runs the same loop.", 1], [11.99, "You plan two or three goals tied to your M.V.P., execute daily and weekly, reflect every week, then reset.", 1], [19.71, "Your Scorecard holds the whole season.", 2], [22.41, "Part 1 holds the M.V.P. you draft in this lesson.", 2], [25.91, "Parts 2 to 4, your Core 4 Play, your game plan, and your weekly check-ins, come in Lesson 5.", 2], [32.29, "Parts 5 and 6, the monthly reflection, then the assessment and reset, come in Lesson 6.", 2], [38.21, "Open it this week and have a look.", 2]], "v": "k1", "cues": [0.05, 9.67, 19.71]}, "n_3_13": {"dur": 6.8, "text": "Back to those two opportunities in the same week. Pick the question you'd ask yourself, and you'll hear where it leads.", "sents": [[0.01, "Back to those two opportunities in the same week.", 0], [3.35, "Pick the question you'd ask yourself, and you'll hear where it leads.", 1]], "v": "v4l", "cues": [0.01, 3.35]}, "n_3_13_o0": {"dur": 9.04, "text": "It's a fair question, but it's about managing your career. It won't tell you which opportunity is actually yours. Try the other option to compare.", "sents": [[0.07, "It's a fair question, but it's about managing your career.", 0], [4.09, "It won't tell you which opportunity is actually yours.", 0], [7.31, "Try the other option to compare.", 0]], "v": "r3", "cues": [0.07]}, "n_3_13_o1": {"dur": 9.04, "text": "That's the tie-breaker. If neither breaks a value, pick the one that serves your purpose. If one does break a value, you already know your answer.", "sents": [[0.13, "That's the tie-breaker.", 0], [1.91, "If neither breaks a value, pick the one that serves your purpose.", 0], [5.81, "If one does break a value, you already know your answer.", 0]], "v": "v4l", "cues": [0.13]}, "n_3_15": {"dur": 14.48, "text": "Time for the drill. This one tests how much certainty you need before you move. Press Play. Melissa will stop to ask what you notice, then ask you to choose, then give you a second decision. Answer each time, and the video carries on.", "sents": [[0, "Time for the drill.", 0], [1.33, "This one tests how much certainty you need before you move.", 0], [5.13, "Press Play.", 1], [6.19, "Melissa will stop to ask what you notice, then ask you to choose, then give you a second decision.", 1], [12.01, "Answer each time, and the video carries on.", 1]], "v": "v4l", "cues": [0, 5.13]}, "n_3_16": {"dur": 32.96, "text": "Your core rep this week is your purpose. It takes about 20 minutes. Draft it using your Lesson 2 notes. It only has to be true, so don't wait for perfection. If you have more time, write your vision as if it's already happened, and fill in the mission template. Read it out loud, and change any word that doesn't sound like you. When your purpose is ready, move it into Part 1 of your Scorecard with your values, and add your vision and mission as you draft them. Both files are on this screen. Run your core rep, then ask one person for feedback on your purpose statement.", "sents": [[0.01, "Your core rep this week is your purpose.", 0], [2.71, "It takes about 20 minutes.", 0], [4.43, "Draft it using your Lesson 2 notes.", 0], [6.71, "It only has to be true, so don't wait for perfection.", 0], [9.93, "If you have more time, write your vision as if it's already happened, and fill in the mission template.", 1], [15.95, "Read it out loud, and change any word that doesn't sound like you.", 1], [19.79, "When your purpose is ready, move it into Part 1 of your Scorecard with your values, and add your vision and mission as you draft them.", 2], [26.89, "Both files are on this screen.", 2], [28.95, "Run your core rep, then ask one person for feedback on your purpose statement.", 3]], "v": "k1", "cues": [0.01, 9.93, 19.79, 28.95]}, "n_3_17": {"dur": 10.32, "text": "This lesson's Athleader Pro is LaChina Robinson, the Pressure Player. She's a broadcaster who performs live, under pressure, for a living. Press Play to hear from her.", "sents": [[0.03, "This lesson's Athleader Pro is LaChina Robinson, the Pressure Player.", 0], [4.81, "She's a broadcaster who performs live, under pressure, for a living.", 0], [8.89, "Press Play to hear from her.", 1]], "v": "v4l", "cues": [0.03, 8.89]}, "n_3_18": {"dur": 15.04, "text": "LaChina's drill trains agility under pressure, and it takes three minutes. Think of a challenge you're facing right now, select Start the timer, and work through each step. When you're done, or once you've planned when you'll run it, select the option that fits.", "sents": [[0.01, "LaChina's drill trains agility under pressure, and it takes three minutes.", 0], [4.01, "Think of a challenge you're facing right now, select Start the timer, and work through each step.", 1], [10.71, "When you're done, or once you've planned when you'll run it, select the option that fits.", 1]], "v": "r3", "cues": [0.01, 4.01]}, "n_3_20_q0": {"dur": 4.96, "text": "A few questions to check the main ideas. Which of these is a mission statement?", "sents": [[0, "A few questions to check the main ideas.", 0], [2.63, "Which of these is a mission statement?", 0]], "v": "v4l", "cues": [0]}, "n_3_20_q1": {"dur": 2.24, "text": "Why do you draft your purpose first?", "sents": [[0.05, "Why do you draft your purpose first?", 0]], "v": "r3", "cues": [0.05]}, "n_3_20_q2": {"dur": 9.04, "text": "Last one. Your purpose is to champion emerging talent, and you're offered a high-profile solo project. What does your purpose suggest?", "sents": [[0.07, "Last one.", 0], [1.27, "Your purpose is to champion emerging talent, and you're offered a high-profile solo project.", 0], [7.35, "What does your purpose suggest?", 0]], "v": "v4l", "cues": [0.07]}, "n_3_20_w0": {"dur": 10.64, "text": "It follows the mission template: an action, who it's for, and what it achieves. The first is a vision, the third is a purpose, and the last is a list of values.", "sents": [[0, "It follows the mission template: an action, who it's for, and what it achieves.", 0], [5.39, "The first is a vision, the third is a purpose, and the last is a list of values.", 0]], "v": "v4l", "cues": [0]}, "n_3_20_w1": {"dur": 6.08, "text": "Purpose is the tie-breaker. When two good options compete, it tells you which one is yours.", "sents": [[0.05, "Purpose is the tie-breaker.", 0], [2.27, "When two good options compete, it tells you which one is yours.", 0]], "v": "r3", "cues": [0.05]}, "n_3_20_w2": {"dur": 8.08, "text": "Your purpose points to a better yes: a way the work can grow someone else. You'll see this exact story in Lesson 4.", "sents": [[0.01, "Your purpose points to a better yes: a way the work can grow someone else.", 0], [5.27, "You'll see this exact story in Lesson 4.", 0]], "v": "v4l", "cues": [0.01]}, "n_3_21": {"dur": 33.28, "text": "Before you go, a quick recap. Your purpose is the tie-breaker. It sits apart from your job title, and when two good options collide, it tells you which one is yours. Your vision is a picture, and your mission is a sentence you can act on tonight. And 90 days is the unit of progress: plan, execute, reflect, and reset, with your Scorecard holding the season. Select Download my answers for a Word document containing what you wrote today. If you'd like to go further, Chapter 5 of the book is all about defining your M.V.P.", "sents": [[0.03, "Before you go, a quick recap.", 0], [2.39, "Your purpose is the tie-breaker.", 1], [4.71, "It sits apart from your job title, and when two good options collide, it tells you which one is yours.", 1], [10.71, "Your vision is a picture, and your mission is a sentence you can act on tonight.", 2], [15.81, "And 90 days is the unit of progress: plan, execute, reflect, and reset, with your Scorecard holding the season.", 3], [23.97, "Select Download my answers for a Word document containing what you wrote today.", 4], [28.21, "If you'd like to go further, Chapter 5 of the book is all about defining your M.V.P.", 4]], "v": "k1", "cues": [0.03, 2.39, 10.71, 15.81, 23.97]}, "n_3_22": {"dur": 15.6, "text": "That's Lesson 3 done. You're halfway through your season, and it shows. This week, run your core rep, your purpose, and ask one person how it landed. Read it out loud every few days. Next time, you'll put your blueprint under pressure.", "sents": [[0, "That's Lesson 3 done.", 0], [1.95, "You're halfway through your season, and it shows.", 0], [4.87, "This week, run your core rep, your purpose, and ask one person how it landed.", 1], [10.37, "Read it out loud every few days.", 1], [12.61, "Next time, you'll put your blueprint under pressure.", 1]], "v": "v4l", "cues": [0, 4.87]}, "n_3_3": {"dur": 6.96, "text": "A quick look back at Lesson 2. What makes something a strength rather than a skill? This one isn't scored.", "sents": [[0.05, "A quick look back at Lesson 2.", 0], [2.23, "What makes something a strength rather than a skill?", 1], [5.33, "This one isn't scored.", 1]], "v": "v4l", "cues": [0.05, 2.23]}, "n_3_4": {"dur": 23.2, "text": "This lesson gives you a way to choose between two good options: a purpose you've written down. You'll draft your purpose in one sentence, separate from your job title. You'll picture where you are in three to five years, in enough detail to see it. And you'll write a mission statement from a simple template. Then you'll move all of it, with your values, into Part 1 of your 90-Day Way Scorecard.", "sents": [[0, "This lesson gives you a way to choose between two good options: a purpose you've written down.", 0], [5.57, "You'll draft your purpose in one sentence, separate from your job title.", 1], [9.81, "You'll picture where you are in three to five years, in enough detail to see it.", 2], [14.53, "And you'll write a mission statement from a simple template.", 3], [17.83, "Then you'll move all of it, with your values, into Part 1 of your 90-Day Way Scorecard.", 4]], "v": "v4l", "cues": [0, 5.57, 9.81, 14.53, 17.83]}, "n_3_7": {"dur": 17.52, "text": "M.V.P. stands for mission, vision, and purpose, plus V for your values. You build it from the foundation up: start with purpose, because purpose is the tie-breaker, then your vision and your mission, with your values underneath all three. Select each one to hear how to test it.", "sents": [[0.01, "M.V.P. stands for mission, vision, and purpose, plus V for your values.", 0], [5.41, "You build it from the foundation up: start with purpose, because purpose is the tie-breaker, then your vision and your mission, with your values underneath all three.", 0], [15.21, "Select each one to hear how to test it.", 1]], "v": "o11", "cues": [0.01, 15.21]}, "n_3_7_mission": {"dur": 9.76, "text": "Your mission is what you do, who it's for, and what it achieves. Use the template on screen, then read it out loud and change any word that doesn't sound like you.", "sents": [[0.01, "Your mission is what you do, who it's for, and what it achieves.", 0], [4.51, "Use the template on screen, then read it out loud and change any word that doesn't sound like you.", 0]], "v": "r3", "cues": [0.01]}, "n_3_7_purpose": {"dur": 9.04, "text": "Your purpose is the impact you want to have, apart from any job. Test it by asking whether it would still be true if you changed employers tomorrow.", "sents": [[0.01, "Your purpose is the impact you want to have, apart from any job.", 0], [4.59, "Test it by asking whether it would still be true if you changed employers tomorrow.", 0]], "v": "v4l", "cues": [0.01]}, "n_3_7_values": {"dur": 12.48, "text": "Your values are the three to five foundations you come back to daily, and they shape your actions. You named them last lesson. If you wouldn't hold one when it costs you something, it's a preference, and you can let it go.", "sents": [[0.01, "Your values are the three to five foundations you come back to daily, and they shape your actions.", 0], [5.95, "You named them last lesson.", 0], [7.65, "If you wouldn't hold one when it costs you something, it's a preference, and you can let it go.", 0]], "v": "v4l", "cues": [0.01]}, "n_3_7_vision": {"dur": 8.72, "text": "Your vision is where you are in three to five years, in real detail. If you can't see it, or name who's in the room with you, keep going.", "sents": [[0.01, "Your vision is where you are in three to five years, in real detail.", 0], [4.91, "If you can't see it, or name who's in the room with you, keep going.", 0]], "v": "v4l", "cues": [0.01]}, "r2_code_pulse": {"dur": 7.36, "text": "Type the code from the last page of the Pulse Check, then select Submit. A quick knowledge check comes next, then your recap.", "sents": [[0.01, "Type the code from the last page of the Pulse Check, then select Submit.", 0], [4.23, "A quick knowledge check comes next, then your recap.", 0]], "v": "r3", "cues": [0.01]}, "r2_form_pulse": {"dur": 8.96, "text": "Answer the five questions, then select Submit. Your code appears on the last page. Copy the code or write it down, then select Next.", "sents": [[0, "Answer the five questions, then select Submit.", 0], [3.25, "Your code appears on the last page.", 0], [5.45, "Copy the code or write it down, then select Next.", 0]], "v": "r3", "cues": [0]}, "r2_pulse": {"dur": 21.36, "text": "Every lesson has the same short Pulse Check, a check-in that helps you see how you're changing over the season. It asks how often you've practiced each of the Core 4 and completed your reps in the last two weeks. It takes about a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing. Select Next, and it opens right here.", "sents": [[0.01, "Every lesson has the same short Pulse Check, a check-in that helps you see how you're changing over the season.", 0], [6.57, "It asks how often you've practiced each of the Core 4 and completed your reps in the last two weeks.", 1], [12.25, "It takes about a minute, and your answers go to the Athleadership team, who use them to see how the whole group is progressing.", 2], [18.83, "Select Next, and it opens right here.", 2]], "v": "k1", "cues": [0.01, 6.57, 12.25]}};
